WITH scored AS (SELECT *, LAST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY channel, promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, LEAD(discount_pct, 1) OVER (ORDER BY discount_pct, id) AS next_discount_pct FROM promotions) SELECT DATE_TRUNC('MONTH', ends_on) AS activity_month, DATE_TRUNC('WEEK', ends_on) AS week_start, COUNT(CASE WHEN promo_code = 'VIP' THEN 1 END) AS vip_count, APPROX_PERCENTILE(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, MAX(discount_pct) FILTER (WHERE promo_code = 'BUNDLE') AS bundle_max_discount_pct, ROUND(SUM(next_discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END), 0), 2) AS next_discount_pct_per_welcome5, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count, ROUND(AVG(discount_pct), 2) AS avg_discount_pct FROM scored GROUP BY DATE_TRUNC('MONTH', ends_on), DATE_TRUNC('WEEK', ends_on);
